class Scope:
    def __enter__(self): return self
    def __exit__(self, typ, value, tb): return False

class Twice:
    def __call__(self, n): return n * 2
print(Twice()(4))

class Key:
    def __init__(self, value): self.value = value
    def __eq__(self, other):
        if not isinstance(other, Key): return NotImplemented
        return self.value == other.value

class Key:
    def __init__(self, value): self.value = value
    def __eq__(self, other): return isinstance(other, Key) and self.value == other.value
    def __hash__(self): return hash(self.value)

class One:
    def __iter__(self):
        yield 1
print(list(One()))

class Vowels:
    def __contains__(self, char): return char in 'aeiou'
print('a' in Vowels())

class Empty:
    def __bool__(self): return False
print(bool(Empty()))

class C:
