class Score:
    def __format__(self, spec): return format(95, spec)
print(f'{Score():03d}')

class Number:
    def __init__(self, value): self.value = value
    def __add__(self, other):
        if not isinstance(other, Number): return NotImplemented
        return Number(self.value + other.value)

